//                            → mints a new cycle and archives nothing, because there is no lead
//
// Neither is reachable from a single tap: each is preceded by its own confirmation screen. The QA
// gate counts the rotate branches, so adding a third fails the build rather than a review.



const STATES = [
  'TG_ENTRY', 'TG_FREEFORM_PROBLEM', 'TG_CONFIRM_CONTEXT', 'TG_OPEN_BRIEF',
  'TG_RESUME_DRAFT', 'TG_SUBMITTED', 'TG_APPEND_MESSAGE', 'TG_NEW_REQUEST_CONFIRM',
  'TG_INFRA_FAILURE'
];

// Callback vocabulary. Short, because Telegram caps callback_data at 64 bytes.
const ACTIONS = {
  DESCRIBE: 'p|describe',        // Описать задачу
  BRIEF: 'p|brief',              // Подготовить бриф
  CONFIRM_OK: 'p|ctx_ok',        // Всё верно
  CONFIRM_FIX: 'p|ctx_fix',      // Исправить
  OPEN: 'p|open',                // Открыть бриф (web_app)
  RESUME: 'p|resume',            // Продолжить
  RESTART: 'p|restart',          // Начать заново  → confirm, never rotates directly
  RESTART_CONFIRM: 'p|restart_y',// Начать новое   → the confirmed discard
  APPEND: 'p|append',            // Добавить к обращению
  NEW: 'p|new',                  // Начать новый вопрос → confirm, never rotates directly
  NEW_CONFIRM: 'p|new_y',        // Начать новый вопрос (confirmed) → THE ONLY ROTATE
  BACK: 'p|back',                // Вернуться
  RETRY: 'p|retry'               // Повторить
};

// Authority snapshot shape, resolved server-side from Bot_Sessions before `decide` is called:
//   { cycle_id, lead_id, lead_cycle_id, has_draft, draft_step, context_extracted }
// `committed` is derived, never trusted from a caller.
function isCommitted(auth) {
  const a = auth || {};
  const lead = String(a.lead_id || '').trim();
  if (!lead) { return false; }
  // A lead from another cycle does not make THIS cycle committed — the existing cycle-semantics
  // gate already invalidates it, and this mirrors that rule rather than re-deriving it.
  return String(a.lead_cycle_id || '').trim() === String(a.cycle_id || '').trim();
}

function hasDraft(auth) {
  const a = auth || {};
  return a.has_draft === true && !isCommitted(a);
}

const screen = (state, copy, extra) => Object.assign({ state: state, copy: copy, rotate: false, writes: [] }, extra || {});

// ---------------------------------------------------------------- the decision

// `input` is { kind: 'command'|'callback'|'text', value }.
function decide(auth, input) {
  const a = auth || {};
  const i = input || {};
  const kind = i.kind;
  const value = String(i.value || '');
  const committed = isCommitted(a);
  const draft = hasDraft(a);

  // ---- /start: the three-way branch. Never rotates. -------------------------
  if (kind === 'command' && (value === '/start' || value === '/menu')) {
    if (committed) { return screen('TG_SUBMITTED', B.TG_COPY.TG_SUBMITTED); }
    if (draft) { return screen('TG_RESUME_DRAFT', B.TG_COPY.TG_RESUME_DRAFT); }
    return screen('TG_ENTRY', B.TG_COPY.TG_ENTRY);
  }

  // ---- committed cycle: only three destinations exist ----------------------
  // This block is the terminal guarantee. It runs BEFORE any qualification branch, so no callback
  // and no free text can reach a qualification state while a committed lead owns the cycle.
  if (committed) {
    if (kind === 'callback' && value === ACTIONS.APPEND) { return screen('TG_APPEND_MESSAGE', B.TG_COPY.TG_APPEND_MESSAGE); }
    if (kind === 'callback' && value === ACTIONS.NEW) { return screen('TG_NEW_REQUEST_CONFIRM', B.TG_COPY.TG_NEW_REQUEST_CONFIRM); }
    if (kind === 'callback' && value === ACTIONS.NEW_CONFIRM) {
      // THE ONLY ROTATE IN THIS FILE.
      return screen('TG_ENTRY', B.TG_COPY.TG_ENTRY, { rotate: true, writes: ['archive_lead', 'new_cycle'] });
    }
    if (kind === 'callback' && value === ACTIONS.BACK) { return screen('TG_SUBMITTED', B.TG_COPY.TG_SUBMITTED); }
    if (kind === 'text' && a.awaiting_append === true) {
      return screen('TG_APPEND_MESSAGE', B.TG_COPY.TG_APPEND_MESSAGE.done, {
        writes: ['activity_append'],
        append_text: value.slice(0, 500)
      });
    }
    // Anything else — a stray tap, a message, an old inline button — lands on the terminal screen.
    return screen('TG_SUBMITTED', B.TG_COPY.TG_SUBMITTED);
  }

  // ---- unfinished draft ----------------------------------------------------
  if (kind === 'callback' && value === ACTIONS.RESUME) {
    return screen('TG_OPEN_BRIEF', B.TG_COPY.TG_OPEN_BRIEF, { resume_step: String(a.draft_step || '') });
  }
  if (kind === 'callback' && value === ACTIONS.RESTART) {
    return screen('TG_NEW_REQUEST_CONFIRM', B.TG_COPY.TG_RESUME_DISCARD_CONFIRM);
  }
  if (kind === 'callback' && value === ACTIONS.RESTART_CONFIRM) {
    // A confirmed discard of an UNCOMMITTED draft. It rotates the cycle for cleanliness but
    // archives no lead, because there is none.
    return screen('TG_ENTRY', B.TG_COPY.TG_ENTRY, { rotate: true, writes: ['new_cycle'] });
  }

  // ---- entry / qualification ----------------------------------------------
  if (kind === 'callback' && value === ACTIONS.DESCRIBE) { return screen('TG_FREEFORM_PROBLEM', B.TG_COPY.TG_FREEFORM_PROBLEM); }
  if (kind === 'callback' && value === ACTIONS.BRIEF) { return screen('TG_OPEN_BRIEF', B.TG_COPY.TG_OPEN_BRIEF); }

  if (kind === 'text' && a.awaiting_problem === true) {
    // The free text is stored as the client's own words. Extraction may propose structure, but
    // everything it proposes is `ai_inferred` and cannot skip a question — see draft-contract.js.
    return screen('TG_CONFIRM_CONTEXT', B.TG_COPY.TG_CONFIRM_CONTEXT, {
      writes: ['free_text'],
      free_text: value.slice(0, 500)
    });
  }

  if (kind === 'callback' && value === ACTIONS.CONFIRM_OK) {
    // «Всё верно» is the only promotion of ai_inferred → user_confirmed, and it is explicit.
    return screen('TG_OPEN_BRIEF', B.TG_COPY.TG_OPEN_BRIEF, { writes: ['confirm_context'] });
  }
  if (kind === 'callback' && value === ACTIONS.CONFIRM_FIX) { return screen('TG_FREEFORM_PROBLEM', B.TG_COPY.TG_FREEFORM_PROBLEM); }

  if (kind === 'callback' && value === ACTIONS.RETRY) { return screen('TG_INFRA_FAILURE', B.TG_COPY.TG_INFRA_FAILURE, { retry: true }); }
  if (kind === 'callback' && value === ACTIONS.BACK) { return screen('TG_ENTRY', B.TG_COPY.TG_ENTRY); }

  return screen('TG_ENTRY', B.TG_COPY.TG_ENTRY);
}

// Which fields TG_CONFIRM_CONTEXT may render. A value with no content renders NO label — never
// «Компания: —» (owner decision C).
function confirmContextSections(extracted) {
  const e = extracted || {};
  const labels = B.TG_COPY.TG_CONFIRM_CONTEXT.labels;
  const out = [];
  for (const key of ['company_name', 'role', 'turnover_band', 'objective', 'problem_summary']) {
    const v = String(e[key] === null || e[key] === undefined ? '' : e[key]).trim();
    if (v) { out.push({ key: key, label: labels[key], value: v }); }
  }
  return out;
}

// The invariant, expressed so a test can call it rather than re-implement it.
function violatesTerminalRule(auth, input, outcome) {
  if (!isCommitted(auth)) { return false; }
  const qualification = ['TG_ENTRY', 'TG_FREEFORM_PROBLEM', 'TG_CONFIRM_CONTEXT', 'TG_OPEN_BRIEF', 'TG_RESUME_DRAFT'];
  const explicitNewRequest = input && input.kind === 'callback' && input.value === ACTIONS.NEW_CONFIRM;
  if (explicitNewRequest) { return false; }
  if (outcome.rotate === true) { return true; }
  return qualification.indexOf(outcome.state) !== -1;
}

// FINMENTOR Premium UX — structured context extraction from free text.
//
// The mechanism that makes TG_CONFIRM_CONTEXT reachable. Until now the state existed, was gated and
// was unreachable, because nothing populated the values it renders.
//
// ── WHAT THIS MODULE IS, AND IS NOT ────────────────────────────────────────────────────────────
//
// It is the GATEKEEPER over extraction, not the extractor's brain. An upstream step — a model, or
// the conservative deterministic pass in `extractDeterministic()` below — PROPOSES a structured
// object. `normalise()` decides what, if anything, is allowed through.
//
// That split is the whole design. A model can say anything; this module can only emit values drawn
// from the approved vocabularies, on the approved fields, marked `ai_inferred` and unconfirmed. An
// unrestricted diagnosis cannot reach the draft because there is no code path that carries one.
//
// ── THE RULES, AND WHERE EACH IS ENFORCED ──────────────────────────────────────────────────────
//
//   1. Only the six supported fields survive. Anything else is DROPPED — `EXTRACTABLE`.
//   2. Everything emitted is `source: 'ai_inferred'`, `confirmed: false` — `toDraftFields()`.
//   3. `ai_inferred` never skips a question. Enforced in draft-contract.js `canSkip()`, which
//      returns false for it; this module never sets `confirmed: true`, so it cannot bypass that.
//   4. TG_CONFIRM_CONTEXT renders only non-empty values — `branches.confirmContextSections()`.
//   5. «Всё верно» promotes ONLY what was shown — `promoteShown()`.
//   6. «Исправить» discards the proposal entirely — `discard()`. Correction must not begin from a
//      silently retained wrong guess.
//   8. `objective` maps only to the exact eight-objective taxonomy — `OBJECTIVE_PATTERNS`.
//   9. Ambiguity yields UNKNOWN, never a guess — every classifier here returns null on a tie, and
//      `turnover_band` is never inferred from PROSE.
//
// (Rules 7, 10, 11, 12 and 13 are properties of what this module does NOT do: it performs no I/O,
// creates no lead, rotates no cycle, and never sees Telegram initData. It is a pure function.)
//
// ── THE LINE THIS MODULE DRAWS ─────────────────────────────────────────────────────────────────
//
// Three categories, and only the first two may produce a value:
//
//   EXPLICIT FACT       the client said it     «Я собственник Demo Retail» -> Demo Retail
//   NORMALISED FACT     arithmetic or a closed vocabulary applied to something explicit
//                       «оборот около 5 млн евро» -> €2–10 млн
//                       «сеть из 6 магазинов»     -> Розничная торговля
//   UNSUPPORTED         everything else — legal form, headcount, geography beyond what was said,
//                       a financing need, a profitability problem inferred from «компания
//                       прибыльная». These stay UNKNOWN however plausible they look.
//
// `turnover_band` was originally never inferred at all, because the bands are money ranges and one
// of them — «Предпочитаю не указывать» — is an explicit refusal. That reasoning still holds for
// prose: «у нас небольшая компания» yields nothing. The owner has authorised the narrow exception
// of a STATED turnover, which is arithmetic rather than inference. The refusal option remains
// unreachable by any code path here: it is a choice the client makes, and a system that can infer
// it has taken that choice away from them.



// Rule 1. The only fields extraction may propose. `problem_summary` is display-only: it is shown on
// the confirmation screen but is NOT a draft field — the client's own words are stored verbatim as
// free text, and the branch `problem` remains a question with approved options.
const EXTRACTABLE = ['company_name', 'business_activity', 'role', 'objective', 'turnover_band', 'problem_summary'];

// Which of those actually become draft fields on confirmation.
const DRAFT_BACKED = ['company_name', 'business_activity', 'role', 'objective', 'turnover_band'];

const MAX_LEN = { company_name: 200, business_activity: 200, role: 200, problem_summary: 300 };

const str = (v) => String(v === null || v === undefined ? '' : v).trim().replace(/\s+/g, ' ');
const norm = (v) => str(v).toLowerCase().replace(/ё/g, 'е');

// ---------------------------------------------------------------- objective (rule 8, rule 9)

// Deliberately narrow. Each objective is recognised only by vocabulary that is unambiguous for it;
// a phrase that fits two objectives scores both and the tie resolves to UNKNOWN.
//
// `independent_view` and `other` are NOT inferable. «Нужен независимый взгляд» is a statement about
// what the client wants from FINMENTOR, not about their situation, and inferring it from a vague
// message would turn "we could not tell" into a product answer. «Другая задача» is the same failure
// wearing a different label. Both remain choices the client makes.
const OBJECTIVE_PATTERNS = {
  financial_management: [
    'управленческ', 'управленческий учет', 'отчетност', 'отчетно', 'бюджет', 'бюджетирован',
    'финансовая функция', 'финансовый директор', 'cfo', 'консолидац', 'закрытие месяца',
    'план-факт', 'планфакт', 'учетная политика'
  ],
  profitability: [
    'маржинальност', 'маржа', 'себестоимост', 'рентабельност', 'прибыльност', 'юнит-экономик',
    'юнит экономик', 'снизить расходы', 'сократить расходы', 'издержк', 'убыточн'
  ],
  cash_flow: [
    'кассовый разрыв', 'кассовые разрывы', 'кассовых разрывов', 'кассовыми разрывами',
    'денежный поток', 'денежного потока', 'денежных средств', 'движение денег', 'движения денег',
    'cash flow', 'cashflow', 'ликвидност', 'нехватка денег', 'не хватает денег',
    'платежный календар', 'дебиторск', 'оборотный капитал',
    // The real UAT text says «прогноз движения денежных средств» and «что будет с деньгами через
    // 2–3 месяца». Neither matched any pattern, so a message that names cash flow four times over
    // scored one point and fell under the two-signal threshold.
    'прогноз движения', 'прогноз денег', 'что будет с деньгами', 'кассового разрыва'
  ],
  investment: [
    'финмодел', 'финансовая модель', 'финансовую модель', 'новый проект', 'новое направление',
    'окупаемост', 'доходность проекта', 'сценарн', 'инвестиционный проект', 'запуск производства'
  ],
  real_estate: [
    'недвижимост', 'помещени', 'здани', 'участок земли', 'аренда помещ', 'купить объект',
    'продажа объекта', 'коммерческая недвижимост'
  ],
  financing: [
    'кредит', 'банк', 'банковск', 'инвестор', 'привлечь финансирован', 'привлечение финансирован',
    'структура капитала', 'заем', 'заём', 'лизинг', 'рефинансир'
  ]
};

// A NEGATED current-setup fact is not an objective. «отдельного CFO нет» describes what the client
// has, and the owner's rule is explicit: carry it as draft context, do not turn it into a top-level
// objective. Left in, it scores `financial_management` off the word "cfo" and competes with the
// objective the client actually described. These spans are removed before scoring, and only these.
const NEGATED_SETUP = [
  /(?:отдельн[а-яё]*\s+)?(?:cfo|финансов[а-яё]+\s+директор[а-яё]*)\s*(?:у\s+нас\s+)?нет/gi,
  /нет\s+(?:отдельн[а-яё]*\s+)?(?:cfo|финансов[а-яё]+\s+директор[а-яё]*)/gi,
  /без\s+(?:отдельн[а-яё]*\s+)?(?:cfo|финансов[а-яё]+\s+директор[а-яё]*)/gi,
  /(?:не\s+ведем|не\s+ведём|нет)\s+(?:бюджет[а-яё]*|управленческ[а-яё]+\s+учет[а-яё]*)/gi
];

// Rule 8 + rule 9. Returns an objective id from the approved taxonomy, or null.
function classifyObjective(text) {
  let t = norm(text);
  if (!t) { return null; }
  for (const re of NEGATED_SETUP) { t = t.replace(re, ' '); }
  const scores = {};
  let best = null;
  let bestScore = 0;
  let tie = false;
  for (const id of Object.keys(OBJECTIVE_PATTERNS)) {
    let n = 0;
    for (const p of OBJECTIVE_PATTERNS[id]) { if (t.indexOf(p) !== -1) { n += 1; } }
    if (n === 0) { continue; }
    scores[id] = n;
    if (n > bestScore) { best = id; bestScore = n; tie = false; }
    else if (n === bestScore) { tie = true; }
  }
  if (!best || tie) { return null; }              // rule 9: ambiguity stays unknown
  // A single incidental keyword is not a classification. Two independent signals, or one signal in
  // a short focused message, is the threshold.
  if (bestScore < 2 && t.length > 160) { return null; }
  // The id must exist in the approved taxonomy. If the taxonomy is ever edited, this fails closed.
  return B.OBJECTIVE_IDS.indexOf(best) !== -1 ? best : null;
}

// ---------------------------------------------------------------- company / role (rule 9)

// ── COMPANY ────────────────────────────────────────────────────────────────────────────────────
//
// Two tiers, and the difference matters.
//
// TIER 1 — the name is DELIMITED: quotes, or an explicit legal form. The delimiter itself says
// "this is a name", so whatever it wraps is taken.
//
// TIER 2 — the name follows an explicit naming construction («Я собственник X», «Компания X»).
// Here nothing marks where the name ends, so the capture is validated by `looksLikeCompanyName`
// before it is believed. Without that validator this tier turns «Я собственник небольшого
// бизнеса» into a company called «небольшого бизнеса», and — from the real UAT text — «Компания
// прибыльная, но…» into a company called «прибыльная». Both are in the negative tests.
const COMPANY_DELIMITED = [
  /«([^»]{2,80})»/,
  /"([^"]{2,80})"/,
  /(?:^|[^А-Яа-яЁёA-Za-z])(?:ООО|АО|ЗАО|ИП|SRL|SA|S\.R\.L\.|GmbH|LLC|Ltd)\s+«?"?([A-Za-zА-Яа-яЁё0-9 .&'-]{2,60})»?"?/i
];

// The naming constructions the owner named, plus their first-person variants. Each captures up to
// a sentence boundary; the validator does the rest.
const COMPANY_NAMED = [
  /(?:^|[^А-Яа-яЁёA-Za-z])я\s+(?:—|-|это)?\s*(?:собственник|владелец|основатель|учредитель|директор|руководитель)\s+([^.,;:!?()]{2,60})/i,
  /(?:^|[^А-Яа-яЁёA-Za-z])(?:наша\s+компания|у\s+нас\s+компания|компания)\s+([^.,;:!?()]{2,60})/i,
  /(?:^|[^А-Яа-яЁёA-Za-z])(?:мы|бизнес)\s+—\s+([^.,;:!?()]{2,60})/i
];

// Words that mean the capture is a description, not a name. A candidate containing any of them is
// refused outright, however it is capitalised.
const NOT_A_NAME = [
  'компани', 'фирм', 'бизнес', 'предприят', 'организац', 'холдинг', 'группа компаний',
  'магазин', 'сеть', 'производств', 'ресторан', 'склад', 'проект', 'клиент', 'сотрудник',
  'команд', 'отдел', 'оборот', 'выручк', 'прибыл', 'убыт', 'проблем', 'ситуац', 'задач',
  'вопрос', 'директор', 'бухгалтер', 'консультант', 'работа', 'услуг', 'товар', 'рынок',
  'котор', 'этот', 'наш', 'свой', 'небольш', 'крупн', 'средн', 'мал'
];

// A name, not a noun phrase: one to four tokens, and at least one token that is either Latin or
// Capitalised. An all-lowercase Cyrillic phrase is ordinary Russian prose and is refused — that
// single rule is what keeps «прибыльная» and «небольшого бизнеса» out.
function looksLikeCompanyName(candidate) {
  const s = str(candidate).replace(/^[«"'\s]+|[»"'\s.]+$/g, '');
  if (s.length < 2 || s.length > 60) { return null; }
  const low = norm(s);
  for (const w of NOT_A_NAME) { if (low.indexOf(w) !== -1) { return null; } }
  const tokens = s.split(/\s+/).filter(Boolean);
  if (!tokens.length || tokens.length > 4) { return null; }
  let strong = 0;
  for (const t of tokens) {
    const bare = t.replace(/[^A-Za-zА-Яа-яЁё0-9&.-]/g, '');
    if (!bare) { continue; }
    if (/^[A-Za-z]/.test(bare)) { strong += 1; continue; }        // Latin token
    if (/^[А-ЯЁ]/.test(bare)) { strong += 1; continue; }          // Capitalised Cyrillic token
  }
  if (!strong) { return null; }
  return s;
}

function extractCompany(text) {
  const raw = str(text);
  for (const re of COMPANY_DELIMITED) {
    const m = raw.match(re);
    if (m && str(m[1])) { return str(m[1]).slice(0, MAX_LEN.company_name); }
  }
  for (const re of COMPANY_NAMED) {
    const m = raw.match(re);
    if (!m) { continue; }
    const name = looksLikeCompanyName(m[1]);
    if (name) { return name.slice(0, MAX_LEN.company_name); }
  }
  return null;
}

// Only first-person role statements. «нам нужен финансовый директор» is a requirement, not a role,
// and must not become «Ваша роль: финансовый директор» on a confirmation screen.
const ROLE_PATTERNS = [
  { re: /(?:^|[^А-Яа-яЁёA-Za-z])(?:я|мы|Я|Мы)\s+(?:—|-|это)?\s*(собственник|учредител[а-яё]*|основател[а-яё]*|владел[а-яё]*)/i, label: 'Собственник' },
  { re: /(?:^|[^А-Яа-яЁёA-Za-z])(?:я|мы|Я|Мы)\s+(?:—|-|это)?\s*(генеральн[а-яё]+ директор|ген\.?\s?директор|CEO)/i, label: 'Генеральный директор' },
  { re: /(?:^|[^А-Яа-яЁёA-Za-z])(?:я|мы|Я|Мы)\s+(?:—|-|это)?\s*(финансов[а-яё]+ директор|CFO)/i, label: 'Финансовый директор' },
  { re: /(?:^|[^А-Яа-яЁёA-Za-z])(?:я|мы|Я|Мы)\s+(?:—|-|это)?\s*(главн[а-яё]+ бухгалтер|финансов[а-яё]+ менеджер|руководител[а-яё]*)/i, label: 'Руководитель' },
  { re: /^\s*(?:я\s+)?(собственник|основател[а-яё]*|владел[а-яё]*)\b/i, label: 'Собственник' }
];

function extractRole(text) {
  const raw = str(text);
  for (const p of ROLE_PATTERNS) { if (p.re.test(raw)) { return p.label; } }
  return null;
}

// ---------------------------------------------------------------- business activity

// A CLOSED vocabulary, normalised — not a phrase captured out of the sentence. The previous version
// copied whatever followed «мы занимаемся», which is an unrestricted classifier wearing a regex:
// it could put any words at all on a consultant's brief. This can only ever emit one of the labels
// below, and «сеть из 6 магазинов» — an explicit operating fact — normalises to Розничная торговля.
//
// Adding an entry here is a product decision, not a tuning knob. Nothing outside this list exists.
const ACTIVITY_VOCAB = [
  ['Розничная торговля', ['магазин', 'магазинов', 'магазина', 'розниц', 'розничн', 'retail', 'торговая точка', 'торговых точек']],
  ['Оптовая торговля', ['оптов', 'опт ', 'wholesale', 'дистрибуц', 'дистрибьют']],
  ['Производство', ['производств', 'завод', 'цех', 'фабрик', 'manufactur']],
  ['Строительство', ['строительств', 'строительн', 'застройщик', 'девелопер', 'подрядн']],
  ['Общественное питание', ['ресторан', 'кафе', 'общепит', 'кофейн', 'пекарн']],
  ['Логистика и транспорт', ['логистик', 'перевозк', 'транспортн', 'грузопереваз', 'грузоперевоз']],
  ['Сельское хозяйство', ['сельск', 'агрохолдинг', 'агропром', 'фермерск']],
  ['IT и разработка', ['разработк', 'it-компан', 'software', 'saas', 'аутсорсинг разработки']]
];

// Ambiguity fails closed: a message that reads as two activities yields none. A company that both
// manufactures and retails is a real thing, and guessing which one to print is worse than asking.
function extractActivity(text) {
  const t = norm(text);
  if (!t) { return null; }
  const hits = [];
  for (const [label, patterns] of ACTIVITY_VOCAB) {
    for (const p of patterns) {
      if (t.indexOf(p) !== -1) { hits.push(label); break; }
    }
  }
  if (hits.length !== 1) { return null; }
  return hits[0];
}

// ---------------------------------------------------------------- scale, from an explicit number

// The module's original rule was that `turnover_band` is NEVER inferred, because the bands are
// money ranges and one of them is an explicit refusal. That rule stands for PROSE — «у нас
// небольшая компания» still yields nothing. The owner has authorised one narrow exception: an
// EXPLICITLY STATED turnover, which is arithmetic rather than inference.
//
// Three things keep it honest:
//   * a turnover word must be nearby, so a loan amount or a property price is not read as revenue;
//   * the currency must be EUR, because the bands are in euro and a conversion would be a guess;
//   * «Предпочитаю не указывать» can never be produced — it is a client's choice, not a fact.
const TURNOVER_WORDS = ['оборот', 'выручк', 'выручка', 'товарооборот', 'turnover', 'revenue', 'продаж'];
const EUR_WORDS = ['евро', 'eur', '€', 'euro'];

function bandFor(millions) {
  if (!(millions >= 0)) { return null; }
  if (millions < 0.5) { return 'до €500 тыс.'; }
  if (millions < 2) { return '€500 тыс. – €2 млн'; }
  if (millions < 10) { return '€2–10 млн'; }
  if (millions < 50) { return '€10–50 млн'; }
  return '€50 млн+';
}

function extractTurnoverBand(text) {
  const t = norm(text);
  if (!t) { return null; }
  // Amounts, with their unit. `5 млн евро`, `€5 млн`, `около 5,5 млн €`, `500 тыс. евро`, `€5m`.
  const re = /(?:€\s*)?(\d+(?:[.,]\d+)?)\s*(?:–|—|-)?\s*(\d+(?:[.,]\d+)?)?\s*(млн|миллион[а-я]*|тыс|тысяч[а-я]*|млрд|миллиард[а-я]*|m\b|k\b)/g;
  const found = [];
  let m;
  while ((m = re.exec(t)) !== null) {
    const around = t.slice(Math.max(0, m.index - 60), m.index + m[0].length + 30);
    if (!TURNOVER_WORDS.some((w) => around.indexOf(w) !== -1)) { continue; }
    if (!EUR_WORDS.some((w) => around.indexOf(w) !== -1)) { continue; }
    const unit = m[3];
    const mult = /млрд|миллиард/.test(unit) ? 1000 : (/тыс/.test(unit) || unit === 'k' ? 0.001 : 1);
    const lo = parseFloat(String(m[1]).replace(',', '.')) * mult;
    const hi = m[2] === undefined ? lo : parseFloat(String(m[2]).replace(',', '.')) * mult;
    found.push([lo, hi]);
  }
  if (found.length !== 1) { return null; }        // no amount, or several — ask instead of guessing
  const [lo, hi] = found[0];
  const a = bandFor(lo);
  const b = bandFor(hi);
  if (!a || !b || a !== b) { return null; }       // a range straddling two bands is not a band
  return a;
}

// ---------------------------------------------------------------- the deterministic pass

// The baseline proposer. Conservative by construction: everything it cannot establish, it leaves
// null. It is also the fallback when no model is configured — the confirmation screen then shows
// whatever little it found, or is skipped entirely.
// The summary is EXTRACTIVE — the client's own sentences, selected, never rewritten. An abstractive
// summary would have to state something the client did not, which is precisely what is forbidden.
// Sentences that describe the problem or the wanted outcome are kept, in the order they were
// written; if none can be identified the whole message is truncated as before, because a summary
// that silently drops the only thing said is worse than a long one.
const PROBLEM_MARKERS = [
  'разрыв', 'не хватает', 'нехватка', 'проблем', 'сложност', 'непонятно', 'не понима',
  'не видим', 'не вижу', 'нет понимания', 'хочу пон', 'хотим пон', 'нужно', 'нужен', 'нужна',
  'настроить', 'наладить', 'навести порядок', 'что будет', 'прогноз', 'риск', 'падает',
  'снижается', 'растут', 'убыт', 'кассов'
];

function summarise(raw) {
  const sentences = str(raw).split(/(?<=[.!?])\s+/).map((s) => str(s)).filter(Boolean);
  const picked = sentences.filter((s) => {
    const low = norm(s);
    return PROBLEM_MARKERS.some((m) => low.indexOf(m) !== -1);
  });
  const chosen = picked.length ? picked.join(' ') : str(raw);
  return chosen.length > MAX_LEN.problem_summary
    ? chosen.slice(0, MAX_LEN.problem_summary).replace(/\s+\S*$/, '') + '…'
    : chosen;
}

function extractDeterministic(text) {
  const raw = str(text);
  if (!raw) { return {}; }
  return {
    company_name: extractCompany(raw),
    business_activity: extractActivity(raw),
    role: extractRole(raw),
    objective: classifyObjective(raw),
    turnover_band: extractTurnoverBand(raw),
    problem_summary: summarise(raw)
  };
}

// ---------------------------------------------------------------- normalisation (the gate)

// Takes ANY proposal — from a model or from the pass above — and returns only what is permitted.
// `dropped` names everything refused, so a proposal that tried to widen the surface is visible
// rather than silently trimmed.
function normalise(proposal) {
  const p = (proposal && typeof proposal === 'object' && !Array.isArray(proposal)) ? proposal : {};
  const out = {};
  const dropped = [];

  for (const key of Object.keys(p)) {
    if (EXTRACTABLE.indexOf(key) === -1) { dropped.push(key); }
  }

  for (const field of EXTRACTABLE) {
    const v = p[field];
    if (v === null || v === undefined) { continue; }
    if (typeof v === 'object') { dropped.push(field + ':not-a-scalar'); continue; }

    if (field === 'objective') {
      // Rule 8. A model may return a label, an id, or something invented. Only an exact match on
      // the approved taxonomy survives; `independent_view` and `other` are not inferable.
      const raw = str(v);
      let id = null;
      if (B.OBJECTIVE_IDS.indexOf(raw) !== -1) { id = raw; }
      else {
        const byLabel = B.objectiveByLabel ? B.objectiveByLabel(raw) : null;
        if (byLabel) { id = byLabel.id; }
      }
      if (!id || id === 'independent_view' || id === 'other') {
        if (raw) { dropped.push('objective:' + raw.slice(0, 40)); }
        continue;
      }
      out.objective = id;
      continue;
    }

    if (field === 'turnover_band') {
      // An enum over the approved bands, and never the refusal. «Предпочитаю не указывать» is a
      // choice the client makes; a system that can infer it has taken that choice away from them.
      const band = str(v);
      if (B.SCALE_OPTIONS.indexOf(band) === -1 || band === 'Предпочитаю не указывать') {
        if (band) { dropped.push('turnover_band:' + band.slice(0, 40)); }
        continue;
      }
      out.turnover_band = band;
      continue;
    }

    const s = str(v);
    if (!s) { continue; }
    out[field] = s.slice(0, MAX_LEN[field] || 200);
  }

  return { fields: out, dropped: dropped };
}

// ---------------------------------------------------------------- the draft envelope (rule 2)

// Everything extraction produces enters the draft as `ai_inferred` and unconfirmed. There is no
// parameter to change that, which is why rule 3 cannot be violated from here: `canSkip()` in
// draft-contract.js returns false for `ai_inferred`, and this never writes anything else.
function toDraftFields(normalised, nowIso) {
  const out = {};
  const f = (normalised && normalised.fields) || {};
  for (const name of DRAFT_BACKED) {
    if (f[name] === undefined) { continue; }
    let value = f[name];
    if (name === 'objective') {
      // The draft contract validates `objective` against B.OBJECTIVE_LABELS, not against ids.
      // The id is the taxonomy-safe internal form — it is what `normalise` can guarantee — and the
      // label is what the draft is allowed to hold. Converting here keeps both true; writing the
      // id straight into the draft produced VALUE_NOT_ALLOWED, which is the contract doing its job.
      const o = B.objectiveById(value);
      if (!o) { continue; }
      value = o.label;
    }
    out[name] = { value: value, source: 'ai_inferred', confirmed: false, at: String(nowIso) };
  }
  return out;
}

// What TG_CONFIRM_CONTEXT will render. Rule 4: a field with no value produces no label, so the
// screen never shows «Компания: —».

// Rule 5. «Всё верно» promotes ONLY the fields that were actually on screen. A value extraction
// produced but did not display cannot be confirmed by a tap the client never saw.

// Rule 6. «Исправить» removes the proposal rather than leaving it in place unconfirmed. Leaving it
// would mean a later screen prefilled with a guess the client has just rejected.
function discard(draft) {
  const next = JSON.parse(JSON.stringify(draft));
  for (const name of DRAFT_BACKED) {
    const f = next.fields[name];
    if (f && f.source === 'ai_inferred' && f.confirmed !== true) {
      next.fields[name] = { value: null, source: null, confirmed: false, at: null };
    }
  }
  return next;
}

// ---------------------------------------------------------------- rendering

// Telegram-safe text. The copy is approved RU prose, so nothing here may re-word it — only
// characters Telegram would misparse are removed.
//
// ON AN HTML SCREEN THE ANGLE BRACKETS MUST SURVIVE. Stripping them is right for plain text
// and destroys the markup here, which is why the mode is passed in rather than assumed. Only
// TG_ENTRY sets it, and only because that screen is entirely static approved copy: a screen
// that renders client-supplied text must escape it before it could ever be sent as HTML.
// Client-derived values are interpolated into an HTML screen, so they are escaped before they
// go anywhere near a tag. safeText deliberately does NOT strip < and > on an HTML screen — the
// authored copy needs its tags — so escaping the VALUES is the only thing standing between a
// client typing "<" and a broken send.
function escapeHtml(value) {
  return String(value === null || value === undefined ? "" : value)
    .split("&").join("&amp;").split("<").join("&lt;").split(">").join("&gt;");
}

function safeText(value, max, html) {
  let t = String(value === null || value === undefined ? "" : value)
    .replace(/\r/g, "")
    .replace(html ? /(?:)/g : /[<>]/g, "")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{4,}/g, "\n\n\n")
    .trim();
  const cap = max || 3800;
  if (t.length > cap) { t = t.slice(0, cap).trim() + "..."; }
  return t;
}

// Which callback each approved action label carries. Built from ACTIONS so a label can never be
// wired to an action that does not exist.
const LABEL_ACTION = {
  "Описать задачу": ACTIONS.DESCRIBE,
  "Подготовить бриф": ACTIONS.BRIEF,
  "Всё верно": ACTIONS.CONFIRM_OK,
  "Исправить": ACTIONS.CONFIRM_FIX,
  "Открыть бриф": ACTIONS.OPEN,
  "Продолжить": ACTIONS.RESUME,
  "Начать заново": ACTIONS.RESTART,
  "Начать новое": ACTIONS.RESTART_CONFIRM,
  "Добавить к обращению": ACTIONS.APPEND,
  "Начать новый вопрос": ACTIONS.NEW,
  "Да, начать новый вопрос": ACTIONS.NEW_CONFIRM,
  "Вернуться": ACTIONS.BACK,
  "Повторить": ACTIONS.RETRY
};

// «Открыть бриф» is the ONLY web_app button. Everything else is a callback, so a stale message
// can never launch the Mini App with an identity the server has not re-resolved.
// A label carries a different action on a CONFIRMATION screen than on the screen that opened it.
// «Начать новый вопрос» appears on three screens: on TG_SUBMITTED and on the append confirmation
// it OPENS the confirmation, and on TG_NEW_REQUEST_CONFIRM it must CONFIRM. With one global
// label->action map it opened the confirmation from inside the confirmation, so the primary
// button re-rendered its own screen and a client could never actually start a new question.
// ACTIONS.NEW_CONFIRM was reachable only through «Да, начать новый вопрос», which no screen
// renders.
//
// Keyed by STATE as well as label, so the fix cannot leak: the discard confirmation reuses the
// TG_NEW_REQUEST_CONFIRM state id but renders «Начать новое», which is not in this table.
const LABEL_ACTION_BY_STATE = {
  TG_NEW_REQUEST_CONFIRM: { "Начать новый вопрос": ACTIONS.NEW_CONFIRM }
};

function buildMarkup(labels, sessionId, state) {
  const perState = LABEL_ACTION_BY_STATE[String(state || "")] || {};
  const rows = [];
  for (const label of labels || []) {
    if (label === "Открыть бриф") {
      rows.push([{ text: label, web_app: { url: MINIAPP_URL } }]);
      continue;
    }
    const action = perState[label] || LABEL_ACTION[label];
    if (!action) { continue; }
    rows.push([{ text: label, callback_data: action }]);
  }
  return rows.length ? { inline_keyboard: rows } : { inline_keyboard: [] };
}

// TG_CONFIRM_CONTEXT is the one screen assembled from data rather than fixed lines. A field with
// no content renders NO label — never «Компания: —» (owner decision C).
function renderCopy(copy, auth) {
  if (!copy) { return { text: "", actions: [] }; }
  if (copy.header) {
    const lines = [copy.header, ""];
    for (const s of confirmContextSections(auth.context_extracted)) {
      lines.push(s.label);
      lines.push("<b>" + escapeHtml(s.value) + "</b>");
      lines.push("");
    }
    lines.push(copy.closing);
    return { text: lines.join("\n"), actions: copy.actions || [] };
  }
  return { text: (copy.text || []).join("\n\n"), actions: copy.actions || [] };
}

// ---------------------------------------------------------------- input

// In the deployed graph this node sits directly after Get Bot Session, which returns the SESSION
// ROW ITSELF, flat — not `{session: {...}}`. The offline harness passes the wrapped shape. Both
// are accepted, because getting this wrong would silently produce an empty session and a bot that
// greets a committed client as a stranger.
const src = $input.first().json;
const session = Object.assign({}, (src && src.session) ? src.session : src);

// The message and the callback come from Parse Telegram Update, which is the only node that has
// them. `$` does not exist in the offline harness, so its absence is a normal case, not an error.
const p = (function () { try { return $("Parse Telegram Update").first().json || {}; } catch (e) { return {}; } })();
const chat_id = String(session.chat_id || src.chat_id || p.chat_id || "");
const text = String(p.message_text || src.message_text || src.text || "");
const data = String(p.callback_data || src.callback_data || src.data || "");

// The authority snapshot is resolved UPSTREAM, from Bot_Sessions, and is read here rather than
// derived from the message. `committed` is never taken from a caller.
const auth = {
  cycle_id: String(session.cycle_id || ""),
  lead_id: String(session.lead_id || ""),
  lead_cycle_id: String(session.lead_cycle_id || ""),
  has_draft: String(session.draft_state || "") === "draft",
  draft_step: String(session.draft_step || ""),
  context_extracted: (function () {
    try { return JSON.parse(session.context_extracted_json || "{}"); } catch (e) { return {}; }
  })(),
  awaiting_problem: String(session.state || "") === "TG_FREEFORM_PROBLEM",
  awaiting_append: String(session.state || "") === "TG_APPEND_MESSAGE"
};

let input;
if (data) { input = { kind: "callback", value: data }; }
else if (text.charAt(0) === "/") { input = { kind: "command", value: text.trim().split(/\s+/)[0] }; }
else { input = { kind: "text", value: text }; }

const stateBefore = String(session.state || "TG_ENTRY");
const outcome = decide(auth, input);

// The terminal rule, asserted on the OUTCOME rather than trusted from the machine. If this ever
// fires the machine has a defect, and the safe answer is the terminal screen — not qualification.
let violated = false;
if (violatesTerminalRule(auth, input, outcome)) {
  violated = true;
  outcome.state = "TG_SUBMITTED";
  outcome.copy = B.TG_COPY.TG_SUBMITTED;
  outcome.rotate = false;
  outcome.writes = [];
}

if (STATES.indexOf(outcome.state) === -1) { outcome.state = "TG_ENTRY"; outcome.copy = B.TG_COPY.TG_ENTRY; }

// An empty or whitespace-only message is not an answer to "describe your situation". Carrying it
// forward would store an empty summary AND — since nothing structured can be found in nothing —
// let the "no structure, skip ahead" rule below march past the one question this screen exists
// to ask. Stay on the screen instead, and write nothing.
if (outcome.state === "TG_CONFIRM_CONTEXT" && (outcome.writes || []).indexOf("free_text") !== -1
    && String(outcome.free_text || "").trim() === "") {
  outcome.state = "TG_FREEFORM_PROBLEM";
  outcome.copy = B.TG_COPY.TG_FREEFORM_PROBLEM;
  outcome.writes = [];
  outcome.free_text = "";
}

// ---------------------------------------------------------------- session writes

const writes = outcome.writes || [];
session.state = outcome.state;

// Cycle rotation is the only destructive write, it happens on exactly two confirmed actions, and
// it archives a lead ONLY when one exists.
if (outcome.rotate === true) {
  if (writes.indexOf("archive_lead") !== -1 && auth.lead_id) {
    session.archived_lead_id = auth.lead_id;
  }
  session.lead_id = "";
  session.lead_cycle_id = "";
  session.draft_state = "";
  session.draft_step = "";
  session.context_extracted_json = "";
  session.cycle_id = "";   // minted by the issuer downstream, never here
}

if (writes.indexOf("free_text") !== -1) { session.free_text_request = safeText(outcome.free_text, 500); }
if (writes.indexOf("confirm_context") !== -1) { session.context_confirmed = "true"; }
if (writes.indexOf("activity_append") !== -1) { session.append_text = safeText(outcome.append_text, 500); }

// ---------------------------------------------------------------- output

// ---------------------------------------------------------------- context extraction

// The free text has just arrived. Extraction proposes structure; `normalise` decides what is
// allowed through. Everything that survives is ai_inferred and unconfirmed, which is why it can
// prefill a later screen but can never skip a question.
if (outcome.state === "TG_CONFIRM_CONTEXT" && (writes || []).indexOf("free_text") !== -1) {
  const proposal = normalise(extractDeterministic(outcome.free_text || text));
  auth.context_extracted = {
    company_name: proposal.fields.company_name || "",
    role: proposal.fields.role || "",
  // The client's OWN answer always wins. Extraction only fills a band the client has not
  // given, and only from a stated turnover — never from prose. «Предпочитаю не указывать»
  // cannot be produced by extraction at all, so a client who chose it keeps that choice.
    turnover_band: String(session.turnover_band || proposal.fields.turnover_band || ""),
    objective: proposal.fields.objective ? (objectiveLabel(proposal.fields.objective) || "") : "",
    problem_summary: proposal.fields.problem_summary || ""
  };
  // Stored so the Mini App can prefill from the same proposal, and so «Всё верно» has
  // something to promote. The draft itself is written by the endpoint, not here.
  session.context_extracted_json = JSON.stringify(auth.context_extracted);
  session.context_confirmed = "false";
}

// «Исправить» must not leave the rejected guess in place — a later screen would prefill from a
// value the client has just told us is wrong.
if (input.kind === "callback" && input.value === ACTIONS.CONFIRM_FIX) {
  session.context_extracted_json = "";
  session.context_confirmed = "false";
}

// The confirmation screen has to EARN its place. «Проверьте, правильно ли FINMENTOR понял ваш
// контекст» is worth asking when extraction found structure — a company, a role, an objective.
// It is not worth asking when the only thing on screen is the client's own sentence read back
// to them: that is a step with no decision in it, and it makes the product look like it
// understood something when it did not.
//
// So the screen renders only when at least one STRUCTURED field survived. `problem_summary` is
// the client's own words and never counts towards that on its own.
const structuralKeys = ["company_name", "role", "turnover_band", "objective"];
const sectionsNow = confirmContextSections(auth.context_extracted);
const hasStructure = sectionsNow.some((s) => structuralKeys.indexOf(s.key) !== -1);
if (outcome.state === "TG_CONFIRM_CONTEXT" && !hasStructure) {
  outcome.state = "TG_OPEN_BRIEF";
  outcome.copy = B.TG_COPY.TG_OPEN_BRIEF;
}

const rendered = renderCopy(outcome.copy, auth);

// The screen declares its own parse mode. Absent means plain text, which is every screen but
// TG_ENTRY — so this changes nothing for any other reply.
const parse_mode = String((outcome.copy && outcome.copy.parse_mode) || "");
const reply_text = safeText(rendered.text, 3800, parse_mode === "HTML");
const reply_markup = buildMarkup(rendered.actions, session.app_session_id, outcome.state);

// lead_ready is FALSE on every premium screen. The premium brief is submitted through
// POST /miniapp/submit, which owns the projection and the privacy record; a second path from
// here would be a second authority for the same lead.
return [{
  json: {
    chat_id: chat_id,
    reply_text: reply_text,
    reply_markup: reply_markup,
    tg_body: { chat_id: chat_id, text: reply_text, reply_markup: reply_markup, parse_mode: parse_mode },
    session: session,
    lead_ready: false,
    lead_payload: null,
    ai_guarded: { enabled: false, model: "", used: false, fallback_used: false },
    debug: {
      state_before: stateBefore,
      state_after: outcome.state,
      detail: violated ? "terminal_rule_enforced" : ("premium_" + outcome.state.toLowerCase()),
      rotate: outcome.rotate === true,
      writes: writes.join(",")
    },
    event: {
      event_type: input.kind,
      state_before: stateBefore,
      state_after: outcome.state,
      message_text: input.kind === "text" ? text : "",
      callback_data: data,
      detail: violated ? "terminal_rule_enforced" : ("premium_" + outcome.state.toLowerCase())
    }
  }
}];
